def shortest_path(edges, start, end):
    """
    Find the shortest path between start and end nodes using Dijkstra's algorithm.

    Args:
        edges: List of (from_node, to_node, weight) tuples representing one-way roads
        start: Starting node
        end: Destination node

    Returns:
        Tuple (distance, path) where distance is total weight and path is ordered list of nodes.
        Returns (None, None) if no path exists.

    Raises:
        ValueError: If any edge weight is negative
    """
    # Handle same node case
    if start == end:
        return (0, [start])

    # Validate edges and build adjacency list
    graph = {}
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight not allowed")

        if from_node not in graph:
            graph[from_node] = []
        graph[from_node].append((to_node, weight))

    # Dijkstra's algorithm
    import heapq

    heap = [(0, start)]  # (distance, node)
    min_dist = {start: 0}
    prev = {start: None}

    while heap:
        dist, node = heapq.heappop(heap)

        # Skip if we've found a better path already
        if node in min_dist and min_dist[node] < dist:
            continue

        if node == end:
            break

        # Process neighbors
        if node in graph:
            for neighbor, weight in graph[node]:
                new_dist = dist + weight

                # Check if we found a shorter path to neighbor
                if neighbor not in min_dist or new_dist < min_dist[neighbor]:
                    min_dist[neighbor] = new_dist
                    prev[neighbor] = node
                    heapq.heappush(heap, (new_dist, neighbor))

    # Check if path exists
    if end not in min_dist:
        return (None, None)

    # Reconstruct path
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = prev[current]

    path.reverse()

    return (min_dist[end], path)
